class UserMailer < ApplicationMailer
  def email_verification(user, token)
    @user = user
    @account = user.account
    @link = Helpdesk::Settings.frontend_link("/verify-email", account: @account.subdomain, token:)
    @ttl_days = (User::EMAIL_VERIFICATION_TTL / 1.day).to_i

    mail(to: user.email, subject: "Verify your email for #{@account.name}")
  end

  def password_reset(user, token)
    @user = user
    @account = user.account
    @link = Helpdesk::Settings.frontend_link("/reset-password", account: @account.subdomain, token:)
    @ttl_hours = (User::PASSWORD_RESET_TTL / 1.hour).to_i

    mail(to: user.email, subject: "Reset your password for #{@account.name}")
  end
end
